select is((select string_agg(p, ',' order by p) from unnest(array['UPDATE', 'DELETE', 'TRUNCATE']) as p where has_table_privilege('postgres', 'public.integrity_timeline_entries', p)), null::text, 'integrity_timeline_entries: UPDATE, DELETE and TRUNCATE are revoked from the owner (append-only)');
