select matches(pg_temp.try($$delete from public.integrity_timeline_entries$$), '^42501 permission denied', 'integrity_timeline_entries: a DELETE by the operator is refused by the revoked privilege');
select matches(pg_temp.try($$truncate public.integrity_timeline_entries$$), '^42501 permission denied', 'integrity_timeline_entries: a TRUNCATE by the operator is refused by the revoked privilege');
grant update, delete, truncate on public.integrity_timeline_entries to postgres;
select is(pg_temp.try($$update public.integrity_timeline_entries set offset_ms = 0$$), 'P0001 TRACE_APPEND_ONLY', 'integrity_timeline_entries: with the privilege re-granted the UPDATE trigger raises TRACE_APPEND_ONLY');
select is(pg_temp.try($$delete from public.integrity_timeline_entries$$), 'P0001 TRACE_APPEND_ONLY', 'integrity_timeline_entries: the DELETE trigger raises TRACE_APPEND_ONLY');
select is(pg_temp.try($$truncate public.integrity_timeline_entries$$), 'P0001 TRACE_APPEND_ONLY', 'integrity_timeline_entries: the TRUNCATE trigger raises TRACE_APPEND_ONLY');
set local session_replication_role = replica;
select is(pg_temp.try($$update public.integrity_timeline_entries set offset_ms = 0$$), 'P0001 TRACE_APPEND_ONLY', 'integrity_timeline_entries: replica mode (ENABLE ALWAYS) still raises TRACE_APPEND_ONLY on UPDATE');
select is(pg_temp.try($$delete from public.integrity_timeline_entries$$), 'P0001 TRACE_APPEND_ONLY', 'integrity_timeline_entries: replica mode still raises TRACE_APPEND_ONLY on DELETE');
select is(pg_temp.try($$truncate public.integrity_timeline_entries$$), 'P0001 TRACE_APPEND_ONLY', 'integrity_timeline_entries: replica mode still raises TRACE_APPEND_ONLY on TRUNCATE');
set local session_replication_role = origin;
revoke update, delete, truncate on public.integrity_timeline_entries from postgres;
