select is((select meets_cutoff from public.quality_cards where session_id = 'a4000000-0000-4000-8000-000000000002'), false, 'rule 6: the api derives "Not reviewed (below cutoff)" from quality_cards.meets_cutoff = false');
select matches(pg_temp.try($$insert into public.quality_cards (org_id, session_id, quality_score_id) values ('a1000000-0000-4000-8000-000000000001', 'a4000000-0000-4000-8000-000000000012', 'a5000000-0000-4000-8000-000000000012')$$), '^42501 permission denied', 'quality_cards I: authenticated (an org owner) has no INSERT');
select matches(pg_temp.try($$update public.quality_cards set score = 0$$), '^42501 permission denied', 'quality_cards U: authenticated has no UPDATE');
select matches(pg_temp.try($$insert into public.integrity_cards (org_id, session_id, integrity_result_id, review_state, photo_missing) values ('a1000000-0000-4000-8000-000000000001', 'a4000000-0000-4000-8000-000000000012', 'a6000000-0000-4000-8000-000000000012', 'reviewed', false)$$), '^42501 permission denied', 'integrity_cards I: authenticated has no INSERT');
select matches(pg_temp.try($$update public.integrity_cards set review_state = 'reviewed'$$), '^42501 permission denied', 'integrity_cards U: authenticated has no UPDATE');
select matches(pg_temp.try($$insert into public.integrity_timeline_entries (org_id, workspace_id, test_id, session_id, integrity_card_id, position, entry_kind, signal_kind, family, rule_id, tier, offset_ms, count, observed, flag_state, signal_seqs) values ('a1000000-0000-4000-8000-000000000001', 'b1000000-0000-4000-8000-000000000001', 'e1000000-0000-4000-8000-000000000001', 'a4000000-0000-4000-8000-000000000004', (select id from public.integrity_cards where session_id = 'a4000000-0000-4000-8000-000000000004'), 9, 'context', 'tab_hidden', 'focus', null, null, 1000, 1, '{"len": 120}', null, '{1}')$$), '^42501 permission denied', 'timeline I: authenticated has no INSERT');
select matches(pg_temp.try($$delete from public.integrity_timeline_entries$$), '^42501 permission denied', 'timeline D: authenticated has no DELETE');
reset role;
reset request.jwt.claims;
select is((select count(*)::int from pg_policies where schemaname = 'public' and tablename in ('integrity_cards', 'integrity_timeline_entries') and cmd = 'SELECT' and 'authenticated' = any (roles) and qual !~ 'reviewed'), 0, 'rule 6: every authenticated SELECT policy on integrity_cards and integrity_timeline_entries carries the review_state = ''reviewed'' clause');
set local role trace_worker;
set local trace.job_org_id = 'a1000000-0000-4000-8000-000000000001';
select matches(pg_temp.try($$select * from public.quality_cards$$), '^42501 permission denied', 'quality_cards S: trace_worker has no privilege');
reset role;
reset trace.job_org_id;
set local role trace_worker;
set local trace.job_org_id = 'a1000000-0000-4000-8000-000000000001';
select matches(pg_temp.try($$select * from public.integrity_cards$$), '^42501 permission denied', 'integrity_cards S: trace_worker has no privilege');
reset role;
reset trace.job_org_id;
set local role trace_worker;
set local trace.job_org_id = 'a1000000-0000-4000-8000-000000000001';
select matches(pg_temp.try($$select * from public.integrity_timeline_entries$$), '^42501 permission denied', 'integrity_timeline_entries S: trace_worker has no privilege');
reset role;
reset trace.job_org_id;
set local role trace_api;
select matches(pg_temp.try($$select * from public.quality_cards$$), '^42501 permission denied', 'quality_cards S: trace_api has no privilege');
reset role;
reset trace.api_org_id;
set local role trace_api;
select matches(pg_temp.try($$select * from public.integrity_cards$$), '^42501 permission denied', 'integrity_cards S: trace_api has no privilege');
reset role;
reset trace.api_org_id;
set local role trace_api;
select matches(pg_temp.try($$select * from public.integrity_timeline_entries$$), '^42501 permission denied', 'integrity_timeline_entries S: trace_api has no privilege');
reset role;
reset trace.api_org_id;
set local role anon;
select matches(pg_temp.try($$select * from public.integrity_cards$$), '^42501 permission denied', 'integrity_cards S: anon has no privilege');
reset role;
set local role trace_candidate;
select matches(pg_temp.try($$select * from public.quality_cards$$), '^42501 permission denied', 'quality_cards S: trace_candidate has no privilege');
reset role;
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.quality_cards', 'select')), 'authenticated,trace_quality_worker', 'quality_cards: exactly authenticated and trace_quality_worker can read it (the other roles hold no SELECT)');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.quality_cards', 'insert')), 'trace_quality_worker', 'quality_cards: exactly trace_quality_worker can insert');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.quality_cards', 'update,delete,truncate,references,trigger')), '', 'quality_cards: no role holds UPDATE, DELETE, TRUNCATE, REFERENCES or TRIGGER');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.integrity_cards', 'select')), 'authenticated,trace_integrity_worker', 'integrity_cards: exactly authenticated and trace_integrity_worker can read it (the other roles hold no SELECT)');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.integrity_cards', 'insert')), 'trace_integrity_worker', 'integrity_cards: exactly trace_integrity_worker can insert');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.integrity_cards', 'update,delete,truncate,references,trigger')), '', 'integrity_cards: no role holds UPDATE, DELETE, TRUNCATE, REFERENCES or TRIGGER');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.integrity_timeline_entries', 'select')), 'authenticated,trace_integrity_worker', 'integrity_timeline_entries: exactly authenticated and trace_integrity_worker can read it (the other roles hold no SELECT)');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.integrity_timeline_entries', 'insert')), 'trace_integrity_worker', 'integrity_timeline_entries: exactly trace_integrity_worker can insert');
select is((select coalesce(string_agg(r, ',' order by r), '') from unnest(array['anon', 'authenticated', 'service_role', 'trace_api', 'trace_candidate', 'trace_candidate_gateway', 'trace_worker', 'trace_quality_worker', 'trace_integrity_worker']) as r where has_table_privilege(r, 'public.integrity_timeline_entries', 'update,delete,truncate,references,trigger')), '', 'integrity_timeline_entries: no role holds UPDATE, DELETE, TRUNCATE, REFERENCES or TRIGGER');

-- ===== DB review m3 m-1: no flag is added once the session's integrity card is final =====
set local role trace_integrity_worker;
set local trace.job_org_id = 'a1000000-0000-4000-8000-000000000001';
select matches(pg_temp.try($$insert into integrity.flags (id, org_id, session_id, rule_id, family, tier, severity, untrusted, raw_media, count, first_offset_ms, state, signal_seqs) values ('a7000000-0000-4000-8000-000000000020', 'a1000000-0000-4000-8000-000000000001', 'a4000000-0000-4000-8000-000000000001', 'D1-UNTRUSTED-INPUT', 'input_origin', 'T3', 'hard', true, false, 1, 1000, 'pending', '{1}')$$), '^42501 TRACE_GUARD', 'flags I: no flag is added once the session''s integrity card is final (its band could no longer match, I-3)');
reset role;
reset trace.job_org_id;
-- ===== DB review m3 m-7b: the single flip re-checks the cutoff and the band against the flags =====
-- C12 is parked awaiting_quality with a Clear band; its quality card (70 of 40, meets the cutoff) lands now, then a
-- pending T3 medium flag is added while the card still waits. Neither final state may be reached.
set local role trace_quality_worker;
set local trace.job_org_id = 'a1000000-0000-4000-8000-000000000001';
select is(pg_temp.try($$insert into public.quality_cards (org_id, session_id, quality_score_id) values ('a1000000-0000-4000-8000-000000000001', 'a4000000-0000-4000-8000-000000000012', 'a5000000-0000-4000-8000-000000000012')$$), 'OK 1', 'm-7b fixture: the late quality card of C12 lands (meets_cutoff = true)');
reset role;
reset trace.job_org_id;
set local role trace_integrity_worker;
set local trace.job_org_id = 'a1000000-0000-4000-8000-000000000001';
select is(pg_temp.try($$insert into integrity.flags (id, org_id, session_id, rule_id, family, tier, severity, untrusted, raw_media, count, first_offset_ms, state, signal_seqs) values ('a7000000-0000-4000-8000-000000000021', 'a1000000-0000-4000-8000-000000000001', 'a4000000-0000-4000-8000-000000000012', 'D1-PASTE', 'paste', 'T3', 'medium', false, false, 1, 1000, 'pending', '{1}')$$), 'OK 1', 'm-7b fixture: a pending T3 medium flag is added while the card waits');
select matches(pg_temp.try($$update public.integrity_cards set review_state = 'not_reviewed_below_cutoff' where session_id = 'a4000000-0000-4000-8000-000000000012'$$), '^42501 TRACE_GUARD: not_reviewed_below_cutoff needs', 'integrity_cards U: the flip to not_reviewed_below_cutoff is refused while meets_cutoff = true (DB review m3 m-7b)');
select matches(pg_temp.try($$update public.integrity_cards set review_state = 'reviewed' where session_id = 'a4000000-0000-4000-8000-000000000012'$$), '^42501 TRACE_GUARD: the band is lower than its flags', 'integrity_cards U: the flip to reviewed is refused when the Clear band no longer matches a T3 medium flag (rule 3, DB review m3 m-7b)');
select is((select review_state::text from public.integrity_cards where session_id = 'a4000000-0000-4000-8000-000000000012'), 'awaiting_quality', 'integrity_cards: after the refused flips C12 still waits (no partial state)');
reset role;
reset trace.job_org_id;
-- ===== DB review m3 m-4: the immutable result tables refuse TRUNCATE (cascade reaches the timeline, whose TRUNCATE is revoked) =====
grant truncate on public.integrity_timeline_entries to postgres;
select matches(pg_temp.try($$truncate quality.scores cascade$$), '^42501 TRACE_GUARD', 'quality.scores: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate public.quality_cards cascade$$), '^42501 TRACE_GUARD', 'quality_cards: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate public.reports$$), '^42501 TRACE_GUARD', 'reports: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate integrity.flags$$), '^42501 TRACE_GUARD', 'integrity.flags: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate integrity.results cascade$$), '^42501 TRACE_GUARD', 'integrity.results: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate public.integrity_cards cascade$$), '^42501 TRACE_GUARD', 'integrity_cards: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
set local session_replication_role = replica;
select matches(pg_temp.try($$truncate quality.scores cascade$$), '^42501 TRACE_GUARD', 'replica: quality.scores: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate public.quality_cards cascade$$), '^42501 TRACE_GUARD', 'replica: quality_cards: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate public.reports$$), '^42501 TRACE_GUARD', 'replica: reports: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate integrity.flags$$), '^42501 TRACE_GUARD', 'replica: integrity.flags: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate integrity.results cascade$$), '^42501 TRACE_GUARD', 'replica: integrity.results: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
select matches(pg_temp.try($$truncate public.integrity_cards cascade$$), '^42501 TRACE_GUARD', 'replica: integrity_cards: TRUNCATE is refused for the operator (immutable, DB review m3 m-4)');
set local session_replication_role = origin;
revoke truncate on public.integrity_timeline_entries from postgres;

select * from finish();
rollback;
